#include "k5-utf8.h"
#include "k5-unicode.h"
#include "ucdata/ucdata.h"

#include <ctype.h>

int
krb5int_ucstrncmp(
                  const krb5_unicode * u1,
                  const krb5_unicode * u2,
                  size_t n)
{
    for (; 0 < n; ++u1, ++u2, --n) {
        if (*u1 != *u2) {
            return *u1 < *u2 ? -1 : +1;
        }
        if (*u1 == 0) {
            return 0;
        }
    }
    return 0;
}

int
krb5int_ucstrncasecmp(
                      const krb5_unicode * u1,
                      const krb5_unicode * u2,
                      size_t n)
{
    for (; 0 < n; ++u1, ++u2, --n) {
        krb5_unicode uu1 = uctolower(*u1);
        krb5_unicode uu2 = uctolower(*u2);

        if (uu1 != uu2) {
            return uu1 < uu2 ? -1 : +1;
        }
        if (uu1 == 0) {
            return 0;
        }
    }
    return 0;
}

krb5_unicode *
krb5int_ucstrnchr(
                  const krb5_unicode * u,
                  size_t n,
                  krb5_unicode c)
{
    for (; 0 < n; ++u, --n) {
        if (*u == c) {
            return (krb5_unicode *) u;
        }
    }

    return NULL;
}

krb5_unicode *
krb5int_ucstrncasechr(
                      const krb5_unicode * u,
                      size_t n,
                      krb5_unicode c)
{
    c = uctolower(c);
    for (; 0 < n; ++u, --n) {
        if ((krb5_unicode) uctolower(*u) == c) {
            return (krb5_unicode *) u;
        }
    }

    return NULL;
}

void
krb5int_ucstr2upper(
                    krb5_unicode * u,
                    size_t n)
{
    for (; 0 < n; ++u, --n) {
        *u = uctoupper(*u);
    }
}

#define TOUPPER(c)  (islower(c) ? toupper(c) : (c))
#define TOLOWER(c)  (isupper(c) ? tolower(c) : (c))

krb5_error_code
krb5int_utf8_normalize(
                       const krb5_data * data,
                       krb5_data ** newdataptr,
                       unsigned flags)
{
    int i, j, len, clen, outpos = 0, ucsoutlen, outsize;
    char *out = NULL, *outtmp, *s;
    krb5_ucs4 *ucs = NULL, *p, *ucsout = NULL;
    krb5_data *newdata;
    krb5_error_code retval = 0;

    static unsigned char mask[] = {
    0, 0x7f, 0x1f, 0x0f, 0x07, 0x03, 0x01};

    unsigned casefold = flags & KRB5_UTF8_CASEFOLD;
    unsigned approx = flags & KRB5_UTF8_APPROX;

    *newdataptr = NULL;

    s = data->data;
    len = data->length;

    newdata = malloc(sizeof(*newdata));
    if (newdata == NULL)
        return ENOMEM;

    /*
     * Should first check to see if string is already in proper normalized
     * form. This is almost as time consuming as the normalization though.
     */

    /* finish off everything up to character before first non-ascii */
    if (KRB5_UTF8_ISASCII(s)) {
        if (casefold) {
            outsize = len + 7;
            out = malloc(outsize);
            if (out == NULL) {
                retval = ENOMEM;
                goto cleanup;
            }

            for (i = 1; (i < len) && KRB5_UTF8_ISASCII(s + i); i++) {
                out[outpos++] = TOLOWER(s[i - 1]);
            }
            if (i == len) {
                out[outpos++] = TOLOWER(s[len - 1]);
                goto cleanup;
            }
        } else {
            for (i = 1; (i < len) && KRB5_UTF8_ISASCII(s + i); i++) {
                /* empty */
            }

            if (i == len) {
                newdata->length = len;
                newdata->data = k5memdup0(s, len, &retval);
                if (newdata->data == NULL)
                    goto cleanup;
                *newdataptr = newdata;
                return 0;
            }
            outsize = len + 7;
            out = malloc(outsize);
            if (out == NULL) {
                retval = ENOMEM;
                goto cleanup;
            }
            outpos = i - 1;
            memcpy(out, s, outpos);
        }
    } else {
        outsize = len + 7;
        out = malloc(outsize);
        if (out == NULL) {
            retval = ENOMEM;
            goto cleanup;
        }
        i = 0;
    }

